            }
        }
    }

    else if (isJsonString(variable)) {
        restoreData(JSON.parse(variable))
        sleepToast("\n💾 恢复数据\n\n✅ 已导入书源数据")
        try { java.upLoginData({"书源设置": ""})} catch(e) {}
