{"content":"<js>
if(java.get("is_bundle")=="false"){
html = java.ajax("https://read.douban.com");
eval(html.match(/Ark\.(user = \{[\s\S]+?\})/)[1]);
cok = user.id??"anonymous";
t = String(java.getString("$.data"));
function name(){
  try {
    const decodedBytes = java.base64DecodeToByteArray(t);
    const totalLen = decodedBytes.length;
    const ivStart = totalLen - 16 - 13;
    const ivBytes = decodedBytes.slice(ivStart, ivStart + 16);
    const encryptedBytes = decodedBytes.slice(0, ivStart);    
    const hashedKey = java.digestHex(cok, "SHA-256");   
    const cipher = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", 
        java.hexDecodeToByteArray(hashedKey), 
        ivBytes
    );

    const decryptedStr = cipher.decryptStr(encryptedBytes);
    const jsonObj = JSON.parse(decryptedStr);
    result = JSON.stringify(jsonObj.posts[0].contents);

} catch (e) {
    java.log("解密错误: " + e);
    result = null;
}
return result
}
ddd = name();
const bbb = book.getVariable("custom");
const sss = source.getVariable();


/*
规范Json数据
const pattern = /:"([\s\S]+?)"(,"|\}|\])/g;
ddd = String(ddd).replace(pattern, (match, content,suffix) => {
  let replacedContent = content.replace(/"/g, '\\"');
  return `:"${replacedContent}"${suffix}`;
}).replace(/\n+/g,'\\n').replace(/[\x00-\x1F\x7F]/g,'');
*/

var data = JSON.parse(String(ddd));
function extractContent(item) {
    const textList = item.data?.text;  
    const process = (content) => {
        if (typeof content === 'string') {    	
        	    if(content==""){   	    	
        	    	content ="\n&lrm;\n"   	    	
        	    	}
            return content;
        }
        if (Array.isArray(content)) {
            return content.map(process).join('');
        }
        if (content && (content.content || content.content==="")) {
          	 let c;   	  
        	  if(content.kind == "footnote"){
        	  	 try{
        	  	 	    book.getVariable();
        	  	 	    c = getImage(content.content)
        	  	 	}catch(e){}

        	  	 if(/1/.test(sss)||/1/.test(bbb))c = "【*"+content.content+"】"
        	  	}else{
        	  		c = content.content
        	  		}
            return process(c);
        }
        return '';
    };
    return  process(textList);
}


function getChapterContent(chapterNumber) {
    let chapterContent = [];
    let currentChapter = -1;
    let isFirstHeadlineFound = false;

    for (let i = 0; i < data.length; i++) {
        let item = data[i];

        if (item.type === 'headline') {
            currentChapter++;
            if (!isFirstHeadlineFound) {
                isFirstHeadlineFound = true;
            }
            if (currentChapter > chapterNumber) {
                break;
            }
        }
        if ((currentChapter === chapterNumber) || (chapterNumber === 0 && !isFirstHeadlineFound && item.type !== 'headline')) {
                if(item.type === "illus")chapterContent.push(`<img src="${item.data?.size.orig.src}">\n`);
                if(item.type !== 'headline')chapterContent.push(extractContent(item));

        }
    }
    return chapterContent.length > 0 ? chapterContent.join('\n') : null;
}

result = "";
// 检查是否需要使用章节逻辑
if (book.bookUrl.includes("ebook")) {    
    let index = chapter.index;
    result = getChapterContent(index);
} else {
    // 遍历数据，提取并拼接 content
    data.forEach(item => {
            if(item.type === "illus")result += `<img src="${item.data?.size.orig.src}">\n`
            result += extractContent(item) + "\n"; // 每个段落换行

    });
}

