		url = "legado://import/addToBookshelf?src="+baseUrl;
		script = `data:text/html;charset=utf-8,
		<html>
		<title>《${bookName}》加入书架</title>		
		<img src="${imgSrc}" style="max-width: 300px; max-height: 400px">
		<p style="text-align: center;"><a href="${url}" style="font-size:50px;">跳转加入书架</a></p>
		<p style="font-size:60px">简介：${info}
		</p>				
		</html>
		<script>
        window.onload = function () {
            window.location.href = '${url}';
