// 根据不同条件为 book.type 赋值
if (device === 'android') {
  if (option) {
    // 如果 option 有内容，安卓阅读赋值为 32
    book.type = 32;
  } else if (genreValue === '1') {
    // 如果 genre 值为 1，安卓阅读赋值为 64
    book.type = 64;
  } else {
    // 默认情况下，安卓阅读赋值为 8
    book.type = 8;
  }
} else if (device === 'ios') {
  if (option) {
    // 如果 option 有内容，苹果源阅赋值为 1
    book.type = 1;
  } else if (genreValue === '1') {
    // 如果 genre 值为 1，苹果源阅赋值为 2
    book.type = 2;
  } else {
    // 默认情况下，苹果源阅赋值为 0
    book.type = 0;
  }
}

